    OUTPUT_HTML = '<!DOCTYPE html><html lang=en><meta charset=UTF-8><title>{title}</title>\n<style>{style}</style>\n<h1>{title}</h1><p>{text}\n{body}'

    def full(self) -> HTTPResponse:
        return HTMLResponse(
            self.OUTPUT_HTML.format(
                title=self.title(),
                text=self.text(),
                style=self.TRACEBACK_STYLE,
                body=self._generate_body(),
            ),
            status=200,
            headers={"Content-Type": "text/html; charset=utf-8"}
        )

    def minimal(self) -> HTTPResponse:
        return HTMLResponse(
            self.OUTPUT_HTML.format(
                title=self.title(),
                text=self.text(),
                style=self.TRACEBACK_STYLE,
                body="",
            ),
            status=200,
            headers={"Content-Type": "text/html; charset=utf-8"}
        )

    def text(self):
        return escape(super().text)

    def title(self):
        return escape(f"⚠️ {super().title}")

    def _generate_body(self):
        _, exc_value, __ = sys.exc_info()
        exceptions = []
        while exc_value:
            exceptions.append(self._format_exc(exc_value))
            exc_value = exc_value.__cause__

        traceback_html = self.TRACEBACK_BORDER.join(reversed(exceptions))
        appname = escape(self.request.app.name)
        name = escape(self.exception.__class__.__name__)
        value = escape(self.exception)
        path = escape(self.request.path)
        lines = [
            f"<h2>Traceback of {appname} (most recent call last):</h2>",
            f"{traceback_html}",
            "<div class=summary><p>",
            f"<b>{name}: {value}</b> while handling path <code>{path}</code>",
            "</div>",
        ]
        return "\n".join(lines)

    def _format_exc(self, exc):
        frames = extract_tb(exc.__traceback__)
        frame_html = "".join(
            self.TRACEBACK_LINE_HTML.format(frame) for frame in frames
        )
        return self.TRACEBACK_WRAPPER_HTML.format(
            exc_name=escape(exc.__class__.__name__),
            exc_value=escape(exc),
            frame_html=frame_html,
        )

