    This class represents a cookie with specific properties such as 'expires', 'path', 'comment', 'domain', 'max-age', 'secure', 'httponly', and 'version'. It includes methods for setting these properties, ensuring that the keys are legal and not reserved words. The class also validates the types of certain properties like 'max-age' and 'expires'.

    Parameters:
        key (str): The name of the cookie. This should be a string representing the cookie name. If the key is a reserved word or contains illegal characters, it will raise a KeyError.
        value: The value to be assigned to the cookie. The type depends on the property being set:
            - For 'max-age', the value must be an integer.
            - For 'expires', the value must be a datetime object.
            - For other properties, the value can be of various types depending on the property (e.g., str for paths and comments).

    Raises:
        KeyError: If the key is a reserved word or contains illegal characters.
        ValueError: If 'max-age' is not an integer or if 'expires' is not a datetime object.
        TypeError: If 'expires' is not a datetime object when setting it.

    Returns:
        None (the function modifies the cookie instance in place).

    Example usage:
        # Creating a new Cookie instance
        my_cookie = Cookie('my_cookie_name', 'my_value')

        # Setting properties
        my_cookie['expires'] = datetime.now()  # Set expires to current time
        my_cookie['max-age'] = 3600  # Set max-age to one hour (in seconds)

        # Accessing values
        print(my_cookie['expires'])  # Outputs the expiration date of the cookie
    """
    _keys = {'expires': 'expires', 'path': 'Path', 'comment': 'Comment', 'domain': 'Domain', 'max-age': 'Max-Age', 'secure': 'Secure', 'httponly': 'HttpOnly', 'version': 'Version'}
    _flags = {'secure', 'httponly'}

    def __init__(self, key, value):
        if key in self._keys:
            raise KeyError("Cookie name is a reserved word")
        if not _is_legal_key(key):
            raise KeyError("Cookie key contains illegal characters")
        self.key = key
        self.value = value
        super().__init__()

    def __setitem__(self, key, value):
        if key not in self._keys:
            raise KeyError("Unknown cookie property")
        if value is not False:
            if key.lower() == "max-age":
                if not str(value).isdigit():
                    raise ValueError("Cookie max-age must be an integer")
            elif key.lower() == "expires":
                if not isinstance(value, datetime):
